1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects -> clients foreign key: H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the truncate and restore it immediately after.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
48	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
49	        // The dashboard's fixed "as of" reference date (Flyway V23) — nothing references it, so a
50	        // plain truncate clears the single row each spec seeds.
51	        jdbc.execute("TRUNCATE TABLE app_clock");
52	    }
53	
54	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
55	    @PostMapping("/seed")
56	    @SuppressWarnings("unchecked")
57	    public void seed(@RequestBody Map<String, Object> fixture) {
58	        // asOf is the fixed reference date the dashboard measures "overdue" against (Flyway V23). A
59	        // spec seeds one so the overdue count is deterministic; stored as the single app_clock row.
60	        Object asOf = fixture.get("asOf");
61	        if (asOf != null) {
62	            jdbc.update("INSERT INTO app_clock (id, as_of) VALUES (1, ?)",
63	                    java.sql.Date.valueOf(asOf.toString()));
64	        }
65	        List<Map<String, Object>> clients = (List<Map<String, Object>>) fixture.get("clients");
66	        if (clients != null) {
67	            for (Map<String, Object> client : clients) {
68	                // archived is optional; default to false (active, matching Flyway V18) when absent.
69	                Object archived = client.get("archived");
70	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
71	                jdbc.update("INSERT INTO clients (id, name, email, archived) VALUES (?, ?, ?, ?)",
72	                        ((Number) client.get("id")).longValue(), client.get("name"),
73	                        client.get("email"),
74	                        archived != null && Boolean.parseBoolean(archived.toString()));
75	            }
76	        }
77	        List<Map<String, Object>> projects = (List<Map<String, Object>>) fixture.get("projects");
78	        if (projects != null) {
79	            for (Map<String, Object> project : projects) {
80	                // status is optional in a fixture; default to ACTIVE (matching Flyway V21) when absent.
81	                Object status = project.get("status");
82	                // archived is optional; default to false (matching Flyway V15) when absent.
83	                Object archived = project.get("archived");
84	                // budget is optional; a project without one has no budget set (NULL, Flyway V22).
85	                Object budget = project.get("budget");
86	                // code is optional; a project without one has no reference code (NULL, Flyway V29).
87	                Object code = project.get("code");
88	                jdbc.update("INSERT INTO projects"
89	                        + " (id, name, client_id, status, archived, budget, code)"
90	                        + " VALUES (?, ?, ?, ?, ?, ?, ?)",
91	                        ((Number) project.get("id")).longValue(), project.get("name"),
92	                        ((Number) project.get("clientId")).longValue(),
93	                        status != null ? status.toString() : "ACTIVE",
94	                        archived != null && Boolean.parseBoolean(archived.toString()),
95	                        budget != null ? new java.math.BigDecimal(budget.toString()) : null,
96	                        code != null ? code.toString() : null);
97	            }
98	        }
99	        List<Map<String, Object>> contacts = (List<Map<String, Object>>) fixture.get("contacts");
100	        if (contacts != null) {
101	            for (Map<String, Object> contact : contacts) {
102	                // primary is optional; default to false (not the main contact, matching Flyway V24).
103	                Object primary = contact.get("primary");
104	                jdbc.update("INSERT INTO contacts (id, client_id, name, email, contact_role, is_primary)"
105	                        + " VALUES (?, ?, ?, ?, ?, ?)",
106	                        ((Number) contact.get("id")).longValue(),
107	                        ((Number) contact.get("clientId")).longValue(), contact.get("name"),
108	                        contact.get("email"), contact.get("role"),
109	                        primary != null && Boolean.parseBoolean(primary.toString()));
110	            }
111	        }
112	        List<Map<String, Object>> tasks = (List<Map<String, Object>>) fixture.get("tasks");
113	        if (tasks != null) {
114	            for (Map<String, Object> task : tasks) {
115	                // done is optional in a fixture; default to false (OPEN) when absent.
116	                Object done = task.get("done");
117	                jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
118	                        ((Number) task.get("id")).longValue(),
119	                        ((Number) task.get("projectId")).longValue(), task.get("title"),
120	                        done != null && Boolean.parseBoolean(done.toString()));
121	            }
122	        }
123	        List<Map<String, Object>> notes = (List<Map<String, Object>>) fixture.get("notes");
124	        if (notes != null) {
125	            long maxId = 0;
126	            for (Map<String, Object> note : notes) {
127	                long id = ((Number) note.get("id")).longValue();
128	                maxId = Math.max(maxId, id);
129	                // `at` is an ISO instant (e.g. "2026-01-05T09:00:00Z"); store it as a UTC
130	                // timestamp so notes sort newest-first by the instant they were written.
131	                jdbc.update("INSERT INTO notes (id, target_type, target_id, note_text, at)"
132	                        + " VALUES (?, ?, ?, ?, ?)",
133	                        id, note.get("targetType"),
134	                        ((Number) note.get("targetId")).longValue(), note.get("text"),
135	                        java.time.OffsetDateTime.ofInstant(
136	                                parseInstant(note.get("at").toString()),
137	                                java.time.ZoneOffset.UTC));
138	            }
139	            // Explicit-id inserts don't advance H2's IDENTITY counter, so a later JPA save() would
140	            // regenerate a seeded id and collide. Restart the counter past the seeded ids.
141	            if (maxId > 0) {
142	                jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxId + 1));
143	            }
144	        }
145	        List<Map<String, Object>> tags = (List<Map<String, Object>>) fixture.get("tags");
146	        if (tags != null) {
147	            for (Map<String, Object> tag : tags) {
148	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
149	                jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
150	                        ((Number) tag.get("id")).longValue(), tag.get("name"));
151	            }
152	        }
153	        List<Map<String, Object>> projectTags =
154	                (List<Map<String, Object>>) fixture.get("projectTags");
155	        if (projectTags != null) {
156	            for (Map<String, Object> link : projectTags) {
157	                // The join row's own id is IDENTITY-generated; the fixture names only the pair.
158	                jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
159	                        ((Number) link.get("projectId")).longValue(),
160	                        ((Number) link.get("tagId")).longValue());
161	            }
162	        }
163	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
164	        if (invoices != null) {
165	            for (Map<String, Object> invoice : invoices) {
166	                // status is optional in a fixture; default to UNPAID (matching Flyway V5) when absent.
167	                Object status = invoice.get("status");
168	                // issuedDate/dueDate are optional; fall back to the Flyway V7 column defaults when absent.
169	                Object issuedDate = invoice.get("issuedDate");
170	                Object dueDate = invoice.get("dueDate");
171	                // discountPct is optional; default to 0 (no discount, matching Flyway V27) when absent.
172	                Object discountPct = invoice.get("discountPct");
173	                // taxPct is optional; default to 0 (no tax, matching Flyway V28) when absent.
174	                Object taxPct = invoice.get("taxPct");
175	                // An invoice is built from line items (Flyway V13). Its amount is the worked-out sum
176	                // of qty * unitPrice across them (zero when there are none yet) — a fixture no longer
177	                // types a figure, it lists what is charged. (An explicit `amount` still wins if a
178	                // fixture gives one, for back-compatibility with lump-sum invoices.)
179	                List<Map<String, Object>> lineItems =
180	                        (List<Map<String, Object>>) invoice.get("lineItems");
181	                java.math.BigDecimal amount = java.math.BigDecimal.ZERO;
182	                if (lineItems != null) {
183	                    for (Map<String, Object> line : lineItems) {
184	                        java.math.BigDecimal unitPrice =
185	                                new java.math.BigDecimal(line.get("unitPrice").toString());
186	                        int qty = ((Number) line.get("qty")).intValue();
187	                        amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
188	                    }
189	                }
