        </strong>
      </p>
      </section>
      <footer>
        <p className="statement-grand-total-line">
          Grand total owed:{' '}
          <strong data-testid="statement-grand-total">
            {formatMoney(data.outstandingTotal)}
          </strong>
        </p>
      </footer>
    </article>
  );
}
